def pancake_sort(arr):
    def flip(arr, i):
        while i > 0:
            arr[i - 1], arr[i - 2] = arr[i - 2], arr[i - 1]
            i -= 1

    n = len(arr)
    for size in range(n, 0, -1):
        # Find the index of the maximum element in the current subarray
        max_idx = max(range(size), key=lambda x: arr[x])

        # Move the maximum element to the front of the subarray
        if max_idx != 0:
            flip(arr, max_idx)

        # Move the maximum element to its correct position at the end of the subarray
        if max_idx != size - 1:
            flip(arr, size - 1)

        # Reduce the size of the subarray for the next iteration
        arr[size - 1] = None  # Mark as placed

    return arr
```

