def magic_square_test(matrix):
    if not matrix or not matrix[0]:
        return False

    n = len(matrix)
    target_sum = sum(matrix[0])

    # Check if all rows have the same sum
    for row in matrix:
        if sum(row) != target_sum:
            return False

    # Check if all columns have the same sum
    for col in range(n):
        col_sum = sum(matrix[row][col] for row in range(n))
        if col_sum != target_sum:
            return False

    # Check if all diagonals have the same sum
    main_diag = sum(matrix[i][i] for i in range(n))
    anti_diag = sum(matrix[i][n - 1 - i] for i in range(n))

    if main_diag != target_sum or anti_diag != target_sum:
        return False

    # Check if all numbers from 1 to n^2 are present exactly once
    seen = set()
    for row in matrix:
        for num in row:
            if not (1 <= num <= n * n):
                return False
            seen.add(num)

    if len(seen) != n * n:
        return False

    return True
```

