def ncr_modp(n, r, p):
    if r < 0 or n < 0 or r > n:
        return 0
    if p == 1:
        return 0
    if p <= n:
        return 0
    # Compute nCr % p using Lucas theorem
    res = 1
    while n > 0:
        ni = n % p
        ri = r % p
        if ni >= ri:
            res = (res * ni) % p
            res = (res * (ni - ri + 1)) % p
        else:
            res = (res * (ni - ri + 1)) % p
        n //= p
        r //= p
    return res
```

